def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a long intact row of the repeating pattern and infer its period.
    candidates = []
    for r in range(3, h):
        vals = [grid[r][c] for c in range(3, w)]
        if len(vals) >= 10 and all(v != 0 for v in vals):
            candidates.append((len(vals), r, vals))
    _, anchor_r, vals = max(candidates)

    period = next(
        p for p in range(2, min(11, len(vals) + 1))
        if all(vals[i] == vals[i % p] for i in range(len(vals)))
    )
    cycle = vals[:period]
    anchor_c = 3

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                i = (r - anchor_r + c - anchor_c) % period
                out[r][c] = cycle[i]
    return out
